        return $null
    }
}

# 一个进程是不是「DSH 那一侧」的。
function Test-DshProcess($Proc) {
    if ($null -eq $Proc) { return $false }
    $cmd = ''
    try { $cmd = [string]$Proc.CommandLine } catch { }
    if ($cmd -like '*dsh-desktop-host*') { return $true }
